using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
namespace DesktopKitten {
    internal sealed class FixtureUpdateFeed:IUpdateFeed {
        internal UpdateOffer Offer;internal byte[] Payload;internal int Checks,Downloads;internal bool Corrupt,Fail,Block;
        internal readonly ManualResetEvent Entered=new ManualResetEvent(false);
        public UpdateOffer Check(Version current,CancellationToken cancel){Interlocked.Increment(ref Checks);Entered.Set();if(Block){cancel.WaitHandle.WaitOne(5000);cancel.ThrowIfCancellationRequested();}if(Fail)throw new System.Net.WebException("fixture offline");return Offer;}
        public string Download(UpdateOffer offer,string stage,CancellationToken cancel,Action<int> progress){Interlocked.Increment(ref Downloads);Entered.Set();if(Block){cancel.WaitHandle.WaitOne(5000);cancel.ThrowIfCancellationRequested();}if(Fail)throw new IOException("fixture download error");var data=(byte[])Payload.Clone();if(Corrupt)data[0]^=1;string path=Path.Combine(stage,offer.Manifest.installerFile);File.WriteAllBytes(path,data);progress(100);return path;}
    }
    public static class UpdateTests {
        static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=1024*1024};}
        static byte[] Bytes(UpdateManifest m){return Encoding.UTF8.GetBytes(Json().Serialize(m));}
        static byte[] Sign(RSACryptoServiceProvider rsa,byte[] bytes){return rsa.SignData(bytes,CryptoConfig.MapNameToOID("SHA256"));}
        static object Release(UpdateManifest m){return Json().DeserializeObject(Json().Serialize(new{tag_name="v"+m.version,draft=false,prerelease=false,assets=new[]{new{name=m.installerFile,size=m.size,digest="sha256:"+m.sha256,browser_download_url=UpdatePolicy.AssetUrl("v"+m.version,m.installerFile)}}}));}
        static void Reject(Action action,Action<bool,string> check,string name){bool failed=false;try{action();}catch(InvalidDataException){failed=true;}catch(IOException){failed=true;}catch(ArgumentException){failed=true;}catch(CryptographicException){failed=true;}catch(FormatException){failed=true;}check(failed,name);}
        internal static UpdateOffer FixtureOffer(RSACryptoServiceProvider rsa,byte[] payload){
            var m=new UpdateManifest{schemaVersion=1,repository=UpdatePolicy.Repository,version="0.1.9.1",channel="stable",platform="win-x64",installerFile=UpdatePolicy.InstallerName("0.1.9.1"),size=payload.Length,notes="草鱼学会了温柔地更新自己。\n保留日程与设置，修复小问题。"};
            using(var sha=SHA256.Create())m.sha256=BitConverter.ToString(sha.ComputeHash(payload)).Replace("-","").ToLowerInvariant();var bytes=Bytes(m);return UpdatePolicy.FromRelease(Release(m),bytes,Sign(rsa,bytes),rsa.ToXmlString(false));
        }
        public static void Run(Action<bool,string> check){
            string root=Path.Combine(Path.GetTempPath(),"grassfish-update-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
            try{using(var rsa=new RSACryptoServiceProvider(2048)){rsa.PersistKeyInCsp=false;byte[] payload=Enumerable.Range(0,4096).Select(n=>(byte)(n%251)).ToArray();var offer=FixtureOffer(rsa,payload);var m=offer.Manifest;string pub=rsa.ToXmlString(false);
                check(UpdatePolicy.Verify(offer.Bytes,offer.Signature,pub).version==m.version,"valid detached RSA/SHA256 update signature");
                Reject(()=>UpdatePolicy.Verify(offer.Bytes,offer.Signature),check,"ephemeral fixture key is not trusted by production client");
                byte[] tampered=(byte[])offer.Bytes.Clone();tampered[tampered.Length/2]^=1;Reject(()=>UpdatePolicy.Verify(tampered,offer.Signature,pub),check,"tampered signed notes rejected");
                byte[] badsig=(byte[])offer.Signature.Clone();badsig[0]^=1;Reject(()=>UpdatePolicy.Verify(offer.Bytes,badsig,pub),check,"tampered detached signature rejected");
                Reject(()=>UpdatePolicy.Verify(offer.Bytes,new byte[0],pub),check,"missing update signature rejected");
                foreach(string field in new[]{"schemaVersion","repository","channel","platform","version","installerFile","sha256","size","notes"}){
                    var copy=Json().Deserialize<UpdateManifest>(Json().Serialize(m));switch(field){case "schemaVersion":copy.schemaVersion=2;break;case "repository":copy.repository="other/pet";break;case "channel":copy.channel="beta";break;case "platform":copy.platform="win-arm64";break;case "version":copy.version="0.1.9";break;case "installerFile":copy.installerFile="../setup.exe";break;case "sha256":copy.sha256="bad";break;case "size":copy.size=UpdatePolicy.MaxInstaller+1;break;case "notes":copy.notes=new string('x',8001);break;}
                    byte[] bytes=Bytes(copy);Reject(()=>UpdatePolicy.Verify(bytes,Sign(rsa,bytes),pub),check,"signed but invalid manifest rejected: "+field);
                }
                foreach(string field in new[]{"draft","prerelease","tag_name","size","digest","browser_download_url"}){
                    var release=JsonValue.Object(Release(m));var asset=JsonValue.Object(JsonValue.Array(release["assets"]).Single());if(field=="draft"||field=="prerelease")release[field]=true;else if(field=="tag_name")release[field]="v0.1.9.2";else asset[field]=field=="size"?(object)(m.size+1):field=="digest"?"sha256:bad":"https://example.invalid/setup.exe";
                    Reject(()=>UpdatePolicy.FromRelease(release,offer.Bytes,offer.Signature,pub),check,"release mismatch rejected: "+field);
                }
                check(UpdatePolicy.ParseVersion("0.1.10.0")>UpdatePolicy.ParseVersion("0.1.9.9"),"versions compared numerically, not as strings");
                check(UpdatePolicy.ParseVersion("0.1.9")==UpdatePolicy.ParseVersion("0.1.9.0"),"numeric normalization blocks same-version reinstall");
                foreach(string value in new[]{"../1","v0.1.9.0","0.1.-1.0","1.2.3.4.5","1.2?x",""})Reject(()=>UpdatePolicy.ParseVersion(value),check,"invalid version rejected: "+value);
                foreach(string address in new[]{"http://github.com/a","https://evil.github.com/a","https://github.com.evil.invalid/a","https://user@github.com/a","https://github.com:444/a","file:///x"})check(!UpdatePolicy.AllowedNetworkUri(new Uri(address)),"download URI rejected: "+address);
                foreach(string host in new[]{"api.github.com","github.com","release-assets.githubusercontent.com","objects.githubusercontent.com"})check(UpdatePolicy.AllowedNetworkUri(new Uri("https://"+host+"/a")),"official HTTPS download host accepted");
                Reject(()=>UpdatePolicy.Inside(root,Path.Combine(root,"..","outside.exe")),check,"path traversal outside staging rejected");Reject(()=>UpdatePolicy.Inside(root,root+"-other/file"),check,"sibling-prefix path rejected");
                string fixture=Path.Combine(root,"payload.exe");File.WriteAllBytes(fixture,payload);UpdatePolicy.VerifyInstaller(fixture,m);check(true,"valid local installer size/hash");File.AppendAllText(fixture,"x");Reject(()=>UpdatePolicy.VerifyInstaller(fixture,m),check,"wrong size installer rejected");File.WriteAllBytes(fixture,new byte[payload.Length]);Reject(()=>UpdatePolicy.VerifyInstaller(fixture,m),check,"same size wrong hash rejected");
                check(UpdatePolicy.InstallBlockReason(0,0,false)==null,"clean app permits update preparation");check(UpdatePolicy.InstallBlockReason(1,0,false).Contains("草稿"),"unsent draft blocks quitting");check(UpdatePolicy.InstallBlockReason(0,1,false).Contains("发送"),"in-flight send blocks quitting");check(UpdatePolicy.InstallBlockReason(0,0,true).Contains("未保存"),"unsaved panel blocks quitting");
                var pref=new UpdatePreferencesStore(Path.Combine(root,"prefs"));DateTime now=new DateTime(2026,10,17,0,0,0,DateTimeKind.Utc);check(pref.Due(now),"new installation auto-check is enabled");pref.Value.LastAttemptUtc=now.ToString("o");check(!pref.Due(now.AddHours(23))&&pref.Due(now.AddDays(1)),"automatic checks at most once every 24 hours");pref.Value.Automatic=false;check(!pref.Due(now.AddDays(2)),"opt-out disables due checks");pref.Value.SkippedVersion=m.version;pref.Save();check(!new UpdatePreferencesStore(Path.Combine(root,"prefs")).Value.Automatic,"updater preferences persist separately from reminders");
                string data=Path.Combine(root,"manager");var feed=new FixtureUpdateFeed{Offer=offer,Payload=payload};using(var manager=new UpdateManager(data,true,a=>a(),feed)){
                    int prompts=0;manager.OfferFound+=manual=>prompts++;manager.Check(false).GetAwaiter().GetResult();check(feed.Checks==1&&feed.Downloads==0&&prompts==1,"startup check offers update without downloading or installing");manager.Check(false).GetAwaiter().GetResult();check(feed.Checks==1,"daily throttle prevents repeated startup requests");manager.Skip();manager.Check(true).GetAwaiter().GetResult();check(feed.Checks==2&&prompts==2,"manual check overrides skipped version and daily throttle");
                    manager.SetAutomatic(false);manager.Check(false).GetAwaiter().GetResult();check(feed.Checks==2,"automatic opt-out honored by manager");manager.Check(true).GetAwaiter().GetResult();check(feed.Checks==3,"manual check still works with automatic disabled");
                    check(manager.Download().GetAwaiter().GetResult()&&File.Exists(Path.Combine(manager.Stage,m.installerFile))&&manager.Phase=="ready","explicit download rechecks installer before ready");
                }
                var skipped=new UpdatePreferencesStore(data);skipped.Value.Automatic=true;skipped.Value.LastAttemptUtc=DateTime.UtcNow.AddDays(-2).ToString("o");skipped.Save();using(var manager=new UpdateManager(data,true,a=>a(),feed)){int n=0;manager.OfferFound+=manual=>n++;manager.Check(false).GetAwaiter().GetResult();check(n==0&&manager.Offer!=null,"skipped version is not automatically prompted");}
                using(var manager=new UpdateManager(Path.Combine(root,"offline"),true,a=>a(),new FixtureUpdateFeed{Fail=true})){manager.Check(true).GetAwaiter().GetResult();check(manager.Phase=="failed"&&!manager.Busy,"network failure leaves app responsive and busy gate clear");}
                var blocked=new FixtureUpdateFeed{Block=true,Offer=offer,Payload=payload};using(var manager=new UpdateManager(Path.Combine(root,"cancel-check"),true,a=>a(),blocked)){
                    Task work=manager.Check(true);check(blocked.Entered.WaitOne(3000),"blocked fixture check entered");manager.Check(true).GetAwaiter().GetResult();check(blocked.Checks==1,"busy gate prevents duplicate update checks");manager.Cancel();work.GetAwaiter().GetResult();check(!manager.Busy&&manager.Phase=="failed","check cancellation releases operation");
                }
                foreach(bool corrupt in new[]{true,false}){var failing=new FixtureUpdateFeed{Offer=offer,Payload=payload,Corrupt=corrupt};using(var manager=new UpdateManager(Path.Combine(root,"bad-"+corrupt),true,a=>a(),failing)){
                    manager.Check(true).GetAwaiter().GetResult();if(!corrupt){failing.Block=true;failing.Entered.Reset();}var work=manager.Download();if(!corrupt){check(failing.Entered.WaitOne(3000),"download fixture entered");check(!manager.Download().GetAwaiter().GetResult(),"duplicate download ignored");manager.Cancel();}check(!work.GetAwaiter().GetResult()&&manager.Stage==null&&!manager.Busy,"invalid/cancelled download never becomes install-ready");
                }}
                var qaFeed=new FixtureUpdateFeed{Offer=offer,Payload=payload};using(var manager=new UpdateManager(Path.Combine(root,"qa"),false,a=>a(),qaFeed)){manager.Check(true).GetAwaiter().GetResult();check(qaFeed.Checks==0&&!manager.Download().GetAwaiter().GetResult(),"isolated UI profile cannot use production network or updater");}
                foreach(string outcome in new[]{"success","failure","wrong-version"}){
                    string target=Path.Combine(root,"target-"+outcome),stage=Path.Combine(root,"stage-"+outcome);Directory.CreateDirectory(Path.Combine(target,"assets"));Directory.CreateDirectory(stage);File.WriteAllText(Path.Combine(target,"DesktopKitten.exe"),"old");File.WriteAllText(Path.Combine(target,"assets","cat.ico"),"old-art");File.WriteAllText(Path.Combine(target,"unrelated.txt"),"do not touch");Directory.CreateDirectory(Path.Combine(target,"other-project"));File.WriteAllText(Path.Combine(target,"other-project","file.txt"),"other");int restarts=0;
                    var plan=new UpdatePlan{Target=target,Stage=stage,Manifest=m};bool result=UpdateHelper.InstallCore(plan,()=>{File.WriteAllText(Path.Combine(target,"DesktopKitten.exe"),"new");return outcome=="failure"?1:0;},()=>outcome!="wrong-version",()=>restarts++,false);
                    check(result==(outcome=="success")&&restarts==1,"fixture installer outcome and one restart: "+outcome);check(File.ReadAllText(Path.Combine(target,"DesktopKitten.exe"))==(outcome=="success"?"new":"old"),"fixture install success/recovery files: "+outcome);check(!File.Exists(Path.Combine(stage,"backup-app","unrelated.txt"))&&!Directory.Exists(Path.Combine(stage,"backup-app","other-project")),"backup never captures unrelated desktop files");check(File.ReadAllText(Path.Combine(target,"unrelated.txt"))=="do not touch","unrelated file preserved during fixture recovery");
                }
                string cancelStage=Path.Combine(root,"launch-cancellation");Directory.CreateDirectory(cancelStage);string first=Guid.NewGuid().ToString("N"),second=Guid.NewGuid().ToString("N");File.WriteAllText(Path.Combine(cancelStage,"update-ticket.json"),Json().Serialize(new UpdateTicket{launchId=first}));UpdateHelper.CancelLaunch(cancelStage);File.WriteAllText(Path.Combine(cancelStage,"update-ticket.json"),Json().Serialize(new UpdateTicket{launchId=second}));UpdateHelper.CancelLaunch(cancelStage);check(File.Exists(Path.Combine(cancelStage,"cancel-update-"+first))&&File.Exists(Path.Combine(cancelStage,"cancel-update-"+second)),"retry cannot erase an earlier helper's cancellation token");
                string brokenTarget=Path.Combine(root,"target-restore-failure"),brokenStage=Path.Combine(root,"stage-restore-failure");Directory.CreateDirectory(brokenTarget);Directory.CreateDirectory(brokenStage);File.WriteAllText(Path.Combine(brokenTarget,"DesktopKitten.exe"),"old");int brokenRestarts=0;bool restoreFailed=false;
                try{UpdateHelper.InstallCore(new UpdatePlan{Target=brokenTarget,Stage=brokenStage,Manifest=m},()=>{File.Delete(Path.Combine(brokenTarget,"DesktopKitten.exe"));Directory.CreateDirectory(Path.Combine(brokenTarget,"DesktopKitten.exe"));return 1;},()=>false,()=>brokenRestarts++,false);}catch(IOException){restoreFailed=true;}catch(UnauthorizedAccessException){restoreFailed=true;}
                check(restoreFailed&&brokenRestarts==0&&File.ReadAllText(Path.Combine(brokenStage,"finished.json")).Contains("restore-failed")&&File.ReadAllText(Path.Combine(brokenStage,"backup-app","DesktopKitten.exe"))=="old","failed recovery is reported honestly and retains usable backup");
                string caches=Path.Combine(root,"caches");Directory.CreateDirectory(caches);for(int n=0;n<5;n++){string d=Path.Combine(caches,n.ToString("x32"));Directory.CreateDirectory(d);File.WriteAllText(Path.Combine(d,".grassfish-update"),"v1");File.WriteAllText(Path.Combine(d,"finished.json"),"{\"phase\":\""+(n==0?"restore-failed":"installed")+"\"}");File.WriteAllText(Path.Combine(d,"dummy"),"x");Directory.SetLastWriteTimeUtc(d,DateTime.UtcNow.AddDays(-30+n));}UpdateCache.Prune(caches,DateTime.UtcNow);check(Directory.GetDirectories(caches).Length==3,"cache cleanup keeps newest two and unresolved backup");check(UpdateCache.LatestResult(caches)!=null,"previous update outcome available on next startup");
            }}finally{string full=Path.GetFullPath(root);if(!Path.GetFileName(full).StartsWith("grassfish-update-tests-",StringComparison.Ordinal))throw new InvalidDataException("invalid test cleanup path");foreach(string f in UpdateCache.Files(full,8192,512L*1024*1024))File.Delete(f);var dirs=Directory.GetDirectories(full,"*",SearchOption.AllDirectories).OrderByDescending(d=>d.Length).ToArray();foreach(string dir in dirs)Directory.Delete(dir,false);Directory.Delete(full,false);}
        }
        public static int VerifyPackage(string stage,string output){
            try{var m=UpdatePolicy.Verify(File.ReadAllBytes(Path.Combine(stage,UpdatePolicy.ManifestName)),Convert.FromBase64String(File.ReadAllText(Path.Combine(stage,UpdatePolicy.SignatureName)).Trim()));UpdatePolicy.VerifyInstaller(Path.Combine(stage,m.installerFile),m);File.WriteAllText(output,Json().Serialize(new{ok=true,version=m.version,productionPinnedKey=true,installed=false,registryModified=false}));return 0;}catch(Exception e){File.WriteAllText(output,Json().Serialize(new{ok=false,error=e.GetType().Name,installed=false}));return 1;}
        }
        public static int CheckNetwork(string output){try{var offer=new GitHubUpdateFeed().Check(AppVersion.Current,CancellationToken.None);File.WriteAllText(output,Json().Serialize(new{ok=true,current=AppVersion.Text,available=offer==null?null:offer.Manifest.version,readOnly=true,downloaded=false,installed=false}));return 0;}catch(Exception e){File.WriteAllText(output,Json().Serialize(new{ok=false,error=e.GetType().Name,readOnly=true,installed=false}));return 1;}}
    }
}
